mkitem!{# [doc = " Polls multiple futures simultaneously, returning a tuple"] # [doc = " of all results once complete."] # [doc = ""] # [doc = " While `join!(a, b).await` is similar to `(a.await, b.await)`,"] # [doc = " `join!` polls both futures concurrently and is therefore more efficient."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(future_join)]"] # [doc = ""] # [doc = " use std::future::join;"] # [doc = ""] # [doc = " async fn one() -> usize { 1 }"] # [doc = " async fn two() -> usize { 2 }"] # [doc = ""] # [doc = " # let _ =  async {"] # [doc = " let x = join!(one(), two()).await;"] # [doc = " assert_eq!(x, (1, 2));"] # [doc = " # };"] # [doc = " ```"] # [doc = ""] # [doc = " `join!` is variadic, so you can pass any number of futures:"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(future_join)]"] # [doc = ""] # [doc = " use std::future::join;"] # [doc = ""] # [doc = " async fn one() -> usize { 1 }"] # [doc = " async fn two() -> usize { 2 }"] # [doc = " async fn three() -> usize { 3 }"] # [doc = ""] # [doc = " # let _ = async {"] # [doc = " let x = join!(one(), two(), three()).await;"] # [doc = " assert_eq!(x, (1, 2, 3));"] # [doc = " # };"] # [doc = " ```"] # [unstable (feature = "future_join" , issue = "91642")] pub macro join ($ ($ fut : expr) ,+ $ (,) ?) { join_internal ! { current_position : [] futures_and_positions : [] munching : [$ ($ fut) +] } }}
mkitem!{# [unstable (feature = "future_join" , issue = "91642")] # [doc = " To be able to *name* the i-th future in the tuple (say we want the .4-th),"] # [doc = " the following trick will be used: `let (_, _, _, _, it, ..) = tuple;`"] # [doc = " In order to do that, we need to generate a `i`-long repetition of `_`,"] # [doc = " for each i-th fut. Hence the recursive muncher approach."] macro join_internal { (current_position : [$ ($ underscores : tt) *] futures_and_positions : [$ ($ acc : tt) *] munching : [$ current : tt $ ($ rest : tt) *]) => (join_internal ! { current_position : [$ ($ underscores) * _] futures_and_positions : [$ ($ acc) * $ current ($ ($ underscores) *)] munching : [$ ($ rest) *] }) , (current_position : $ _ : tt futures_and_positions : [$ ($ fut_expr : tt ($ ($ pos : tt) *)) *] munching : []) => (match ($ (MaybeDone :: Future ($ fut_expr) ,) *) { futures => async { let mut futures = futures ; let mut futures = unsafe { Pin :: new_unchecked (& mut futures) } ; poll_fn (move | cx | { let mut done = true ; $ (let fut = unsafe { futures . as_mut () . map_unchecked_mut (| it | { let ($ ($ pos ,) * fut , ..) = it ; fut }) } ; done &= fut . poll (cx) . is_ready () ;) * if ! done { return Poll :: Pending ; } let futures = unsafe { futures . as_mut () . get_unchecked_mut () } ; Poll :: Ready (($ ({ let ($ ($ pos ,) * fut , ..) = & mut * futures ; fut . take_output () . unwrap () }) ,*)) }) . await } }) , }}
mkitem!{mkenum!{# [doc = " Future used by `join!` that stores it's output to"] # [doc = " be later taken and doesn't panic when polled after ready."] # [doc = ""] # [doc = " This type is public in a private module for use by the macro."] # [allow (missing_debug_implementations)] # [unstable (feature = "future_join" , issue = "91642")] pub enum MaybeDone < F : Future > { Future (F) , Done (F :: Output) , Taken , }}}
mkitem!{mkimpl!{# [unstable (feature = "future_join" , issue = "91642")] impl < F : Future > MaybeDone < F > { pub fn take_output (& mut self) -> Option < F :: Output > { match * self { MaybeDone :: Done (_) => match mem :: replace (self , Self :: Taken) { MaybeDone :: Done (val) => Some (val) , _ => unreachable ! () , } , _ => None , } } }}}
mkitem!{mkimpl!{# [unstable (feature = "future_join" , issue = "91642")] impl < F : Future > Future for MaybeDone < F > { type Output = () ; fn poll (mut self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Self :: Output > { unsafe { match * self . as_mut () . get_unchecked_mut () { MaybeDone :: Future (ref mut f) => { let val = ready ! (Pin :: new_unchecked (f) . poll (cx)) ; self . set (Self :: Done (val)) ; } MaybeDone :: Done (_) => { } MaybeDone :: Taken => unreachable ! () , } } Poll :: Ready (()) } }}}